import{_ as l,a0 as t,w as o,s as r,ao as d,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 上查看和配置密碼時效 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上查看和配置密碼時效 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上查看和配置密碼時效 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上查看和配置密碼時效 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200317 Viewing and configuring password aging on Linux","title":"在 Linux 上查看和配置密碼時效","tag":"202003","desc":""},"relativePath":"202003/20200317 Viewing and configuring password aging on Linux.md","filePath":"[post].md"}'),c={name:"202003/20200317 Viewing and configuring password aging on Linux.md"};function g(u,s,h,b,w,k){const n=t("Link");return o(),r("div",null,[s[18]||(s[18]=d(`<h1 id="在-linux-上查看和配置密碼時效" tabindex="-1">在 Linux 上查看和配置密碼時效 <a class="header-anchor" href="#在-linux-上查看和配置密碼時效" aria-label="Permalink to “在 Linux 上查看和配置密碼時效”">​</a></h1><p><img src="https://images.idgesg.net/images/article/2019/09/cso_nw_user_id_password_credentials_authentication_by_bluebay2014_gettyimages-924698706_2400x1600-100811223-large.jpg" alt=""></p><blockquote><p>使用正確的設置，可以強制 Linux 用户定期更改密碼。以下是查看密碼時效以及如何更改其中設置的方法。</p></blockquote><p>可以將 Linux 系統上的用户密碼配置為永久或設置過期時間，以讓人們必須定期重置它們。出於安全原因，通常認為定期更改密碼是一種好習慣，但默認並未配置。</p><p>要查看和修改密碼時效，你需要熟悉幾個重要的命令：<code>chage</code> 命令及其 <code>-l</code> 選項，以及 <code>passwd</code> 命令及其 <code>-S</code> 選項。本文會介紹這些命令，還有其他一些 <code>chage</code> 命令選項來配置密碼時效。</p><h3 id="查看密碼時效設置" tabindex="-1">查看密碼時效設置 <a class="header-anchor" href="#查看密碼時效設置" aria-label="Permalink to “查看密碼時效設置”">​</a></h3><p>確定某個特定帳户是否已設置密碼時效的方法是使用如下 <code>chage</code> 命令。請注意，除了你自己的帳户以外，其他任何帳户都需要 root 權限。請注意下面的密碼到期日期。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -l dory</span></span>
<span class="line"><span>Last password change                                    : Mar 15, 2020</span></span>
<span class="line"><span>Password expires                                        : Jun 13, 2020    &lt;==</span></span>
<span class="line"><span>Password inactive                                       : never</span></span>
<span class="line"><span>Account expires                                         : never</span></span>
<span class="line"><span>Minimum number of days between password change          : 10</span></span>
<span class="line"><span>Maximum number of days between password change          : 90</span></span>
<span class="line"><span>Number of days of warning before password expires       : 14</span></span></code></pre></div><p>如果未應用密碼時效，那麼帳户信息將如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -l nemo</span></span>
<span class="line"><span>Last password change                                    : Jan 14, 2019</span></span>
<span class="line"><span>Password expires                                        : never         &lt;==</span></span>
<span class="line"><span>Password inactive                                       : never</span></span>
<span class="line"><span>Account expires                                         : Mar 26, 2706989</span></span>
<span class="line"><span>Minimum number of days between password change          : 0</span></span>
<span class="line"><span>Maximum number of days between password change          : 99999</span></span>
<span class="line"><span>Number of days of warning before password expires       : 7</span></span></code></pre></div><p>你也可以使用 <code>passwd -S</code> 命令查看某些信息，但是你需要知道輸出中的每個字段代表什麼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dory$ passwd -S</span></span>
<span class="line"><span>dory P 03/15/2020 10 90 14 -1</span></span></code></pre></div><p>這裏的七個字段代表：</p><ul><li>1 – 用户名</li><li>2 - 帳户狀態（<code>L</code> = 鎖定，<code>NP</code> = 無密碼，<code>P</code> = 可用密碼）</li><li>3 – 上次密碼更改的日期</li><li>4 – 可更改最低時效（如果沒有這麼多天，則不能更改密碼）</li><li>5 – 最長時效（這些天后，密碼必須更改）</li><li>6 – 密碼過期前提前警告的天數</li><li>7 – 密碼過期後鎖定之前的天數（設為無效）</li></ul><p>需要注意的一件事是，<code>chage</code> 命令不會顯示帳户是否被鎖定；它僅顯示密碼時效設置。另一方面，<code>passwd -S</code> 命令將告訴你密碼被鎖定的時間。在此例中，請注意帳户狀態為 <code>L</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo passwd -S dorothy</span></span>
<span class="line"><span>dorothy L 07/09/2019 0 99999 7 10</span></span></code></pre></div><p>通過將 <code>/etc/shadow</code> 文件中通常包含密碼的“哈希”字段變為 <code>!</code>，從而達成鎖定的效果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo grep dorothy /etc/shadow</span></span>
<span class="line"><span>dorothy:!:18086:0:99999:7:10::    &lt;==</span></span></code></pre></div><p>帳户被鎖定的事實在 <code>chage</code> 輸出中並不明顯：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -l dorothy</span></span>
<span class="line"><span>Last password change                                    : Jul 09, 2019</span></span>
<span class="line"><span>Password expires                                        : never</span></span>
<span class="line"><span>Password inactive                                       : never</span></span>
<span class="line"><span>Account expires                                         : never</span></span>
<span class="line"><span>Minimum number of days between password change          : 0</span></span>
<span class="line"><span>Maximum number of days between password change          : 99999</span></span>
<span class="line"><span>Number of days of warning before password expires       : 7</span></span></code></pre></div><h3 id="密碼時效的一些選項" tabindex="-1">密碼時效的一些選項 <a class="header-anchor" href="#密碼時效的一些選項" aria-label="Permalink to “密碼時效的一些選項”">​</a></h3><p>最常用的設置是最短和最長的天數。它們經常結合使用。例如，你可以配置一個密碼，使其最長不能使用超過 90 天（最大），然後添加一個有效期為一週或 10 天（最小）的密碼。這樣可以確保用户不會在需要更改密碼後馬上改回以前的密碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -M 90 -m 10 shark</span></span>
<span class="line"><span>$ sudo chage -l shark</span></span>
<span class="line"><span>Last password change                                    : Mar 16, 2020</span></span>
<span class="line"><span>Password expires                                        : Jun 14, 2020</span></span>
<span class="line"><span>Password inactive                                       : never</span></span>
<span class="line"><span>Account expires                                         : never</span></span>
<span class="line"><span>Minimum number of days between password change          : 10    &lt;==</span></span>
<span class="line"><span>Maximum number of days between password change          : 90    &lt;==</span></span>
<span class="line"><span>Number of days of warning before password expires       : 7</span></span></code></pre></div><p>你還可以使用 <code>-E</code> 選項為帳户設置特定的到期日期。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -E 2020-11-11 tadpole</span></span>
<span class="line"><span>$ sudo chage -l tadpole</span></span>
<span class="line"><span>Last password change                                    : Oct 15, 2019</span></span>
<span class="line"><span>Password expires                                        : never</span></span>
<span class="line"><span>Password inactive                                       : never</span></span>
<span class="line"><span>Account expires                                         : Nov 11, 2020  &lt;==</span></span>
<span class="line"><span>Minimum number of days between password change          : 0</span></span>
<span class="line"><span>Maximum number of days between password change          : 99999</span></span>
<span class="line"><span>Number of days of warning before password expires       : 7</span></span></code></pre></div>`,25)),p("p",null,[s[1]||(s[1]=a("密碼時效可能是一個重要的選擇，只要它不鼓勵用户使用過於簡單的密碼或以不安全的方式寫下來即可。有關控制密碼字符（例如，大小寫字母、數字等的組合）的更多信息，請參考這篇關於",-1)),e(n,{href:"https://www.networkworld.com/article/2726217/how-to-enforce-password-complexity-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[a("密碼複雜度",-1)])]),_:1}),s[2]||(s[2]=a("的文章。",-1))]),s[19]||(s[19]=p("hr",null,null,-1)),p("p",null,[s[4]||(s[4]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3532815/viewing-and-configuring-password-aging-on-linux.html"},{default:i(()=>[...s[3]||(s[3]=[a("https://www.networkworld.com/article/3532815/viewing-and-configuring-password-aging-on-linux.html",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[5]||(s[5]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[7]||(s[7]=[a("geekpi",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const y=l(c,[["render",g]]);export{x as __pageData,y as default};
